/* ==========================================================================
   店舗別月別来客数ダッシュボード スタイルシート
   ========================================================================== */

:root {
  --color-bg-page: #f8fafc;
  --color-bg-card: #ffffff;
  --color-text-main: #1e293b;
  --color-text-muted: #64748b;
  --color-text-light: #94a3b8;
  --color-border: #e2e8f0;
  --color-border-hover: #cbd5e1;
  --color-primary: #3b82f6;
  --color-primary-dark: #2563eb;
  --color-primary-light: #eff6ff;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-full: 9999px;
  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.05), 0 1px 2px rgba(0, 0, 0, 0.03);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji";
  --transition-normal: 0.2s ease;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--color-bg-page);
  color: var(--color-text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* メインコンテナ */
.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 16px 48px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

@media (min-width: 768px) {
  .app-container {
    padding: 36px 24px 60px;
    gap: 32px;
  }
}

/* ヘッダー */
.app-header {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.header-title {
  font-size: 1.625rem;
  font-weight: 700;
  color: var(--color-text-main);
  letter-spacing: -0.02em;
}

@media (min-width: 768px) {
  .header-title {
    font-size: 2rem;
  }
}

.header-subtitle {
  font-size: 0.95rem;
  color: var(--color-text-muted);
}

/* 操作パネル（期間フィルター & 店舗表示切替） */
.control-panel {
  background-color: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

@media (min-width: 768px) {
  .control-panel {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    padding: 20px 24px;
  }
}

/* 期間フィルター */
.filter-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.filter-label {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.filter-btn-group {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.filter-btn {
  background-color: var(--color-bg-page);
  border: 1px solid var(--color-border);
  color: var(--color-text-main);
  font-size: 0.875rem;
  font-weight: 500;
  padding: 8px 16px;
  border-radius: var(--radius-full);
  cursor: pointer;
  transition: all var(--transition-normal);
  user-select: none;
  min-height: 38px;
}

.filter-btn:hover {
  background-color: #f1f5f9;
  border-color: var(--color-border-hover);
}

.filter-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.3);
}

.filter-btn.filter-btn-active {
  background-color: var(--color-primary);
  border-color: var(--color-primary);
  color: #ffffff;
  font-weight: 600;
  box-shadow: 0 2px 4px rgba(37, 99, 235, 0.25);
}

/* 店舗表示トグル */
.store-toggles {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
}

.store-toggle-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px 6px 8px;
  background-color: var(--color-bg-page);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-full);
  cursor: pointer;
  font-size: 0.875rem;
  font-weight: 500;
  user-select: none;
  transition: background-color var(--transition-normal), border-color var(--transition-normal);
}

.store-toggle-item:hover {
  background-color: #f1f5f9;
  border-color: var(--color-border-hover);
}

.store-checkbox {
  appearance: none;
  -webkit-appearance: none;
  width: 18px;
  height: 18px;
  border: 2px solid var(--color-text-light);
  border-radius: 4px;
  outline: none;
  cursor: pointer;
  display: grid;
  place-content: center;
  transition: background-color 0.15s ease, border-color 0.15s ease;
  background-color: #ffffff;
}

.store-checkbox:checked {
  background-color: var(--color-primary);
  border-color: var(--color-primary);
}

.store-checkbox:checked::before {
  content: "";
  width: 9px;
  height: 5px;
  border-left: 2px solid #ffffff;
  border-bottom: 2px solid #ffffff;
  transform: rotate(-45deg) translate(1px, -1px);
}

.store-checkbox:focus-visible {
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.35);
}

.store-color-badge {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: var(--radius-full);
  flex-shrink: 0;
}

/* リセットボタン */
.reset-btn {
  background: transparent;
  border: 1px dashed var(--color-border);
  color: var(--color-text-muted);
  font-size: 0.8125rem;
  font-weight: 500;
  padding: 6px 12px;
  border-radius: var(--radius-full);
  cursor: pointer;
  transition: all var(--transition-normal);
  align-self: flex-start;
}

.reset-btn:hover {
  border-color: var(--color-text-muted);
  color: var(--color-text-main);
  background-color: #f8fafc;
}

.reset-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px rgba(100, 116, 139, 0.25);
}

@media (min-width: 768px) {
  .reset-btn {
    align-self: auto;
  }
}

/* サマリーカード一覧 */
.summary-grid {
  display: grid;
  grid-template-columns: repeat(1, minmax(0, 1fr));
  gap: 16px;
}

@media (min-width: 640px) {
  .summary-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (min-width: 1024px) {
  .summary-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 20px;
  }
}

.summary-card {
  background-color: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 10px;
  transition: transform var(--transition-normal), box-shadow var(--transition-normal);
  position: relative;
  overflow: hidden;
}

.summary-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.summary-empty-card,
.summary-grid > .summary-card:only-child {
  grid-column: 1 / -1;
}

.summary-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.summary-title {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--color-text-main);
  display: flex;
  align-items: center;
  gap: 8px;
}

.summary-value {
  font-size: 1.875rem;
  font-weight: 700;
  color: var(--color-text-main);
  line-height: 1.1;
  letter-spacing: -0.03em;
}

.summary-value small {
  font-size: 1rem;
  font-weight: 500;
  margin-left: 4px;
  color: var(--color-text-muted);
}

.summary-subtext {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  display: flex;
  flex-direction: column;
  gap: 4px;
  border-top: 1px dashed var(--color-border);
  padding-top: 10px;
  margin-top: 4px;
}

.summary-subtext-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.summary-subtext-item strong {
  color: var(--color-text-main);
  font-weight: 600;
}

/* グラフエリア */
.chart-card {
  background-color: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

@media (min-width: 768px) {
  .chart-card {
    padding: 28px;
    gap: 20px;
  }
}

.chart-header {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

@media (min-width: 640px) {
  .chart-header {
    flex-direction: row;
    align-items: baseline;
    justify-content: space-between;
  }
}

.chart-title {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-text-main);
  letter-spacing: -0.01em;
}

.chart-subtitle {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
}

.chart-wrapper {
  width: 100%;
  height: 380px;
  min-height: 320px;
}

@media (min-width: 768px) {
  .chart-wrapper {
    height: 440px;
  }
}

/* Recharts カスタムツールチップ */
.custom-tooltip {
  background-color: rgba(255, 255, 255, 0.96);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  padding: 12px 14px;
  min-width: 160px;
  backdrop-filter: blur(4px);
}

.tooltip-label {
  font-size: 0.8125rem;
  font-weight: 700;
  color: var(--color-text-main);
  margin-bottom: 8px;
  border-bottom: 1px solid var(--color-border);
  padding-bottom: 4px;
}

.tooltip-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  font-size: 0.8125rem;
  color: var(--color-text-main);
  padding: 3px 0;
}

.tooltip-item-left {
  display: flex;
  align-items: center;
  gap: 6px;
}

.tooltip-color-dot {
  width: 8px;
  height: 8px;
  border-radius: var(--radius-full);
  display: inline-block;
  flex-shrink: 0;
}

.tooltip-item-value {
  font-weight: 600;
  color: var(--color-text-main);
}

/* 空状態メッセージ・補助表示 */
.chart-empty-message {
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  color: var(--color-text-muted);
  font-size: 0.95rem;
  text-align: center;
  padding: 24px;
}

/* 凡例カスタムスタイル */
.chart-wrapper .recharts-default-legend {
  display: flex;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
  margin-top: 12px;
  padding: 0;
}

.chart-wrapper .recharts-legend-item {
  cursor: pointer;
  font-size: 0.8125rem;
  font-weight: 500;
}

export type StoreKey = 'shibuya' | 'shinjuku' | 'ikebukuro';

export type FilterPeriod = 'all' | 'first-half' | 'second-half' | 'last-3-months';

export type VisibleStoresState = Record<StoreKey, boolean>;

export interface MonthlyVisitorRecord {
  month: string;
  shibuya: number;
  shinjuku: number;
  ikebukuro: number;
}

export interface StoreConfig {
  id: StoreKey;
  name: string;
  color: string;
  key: StoreKey;
}

export interface StoreStats {
  id: StoreKey;
  name: string;
  color: string;
  total: number;
  average: number;
  maxMonth: string;
  maxValue: number;
}

import { MonthlyVisitorRecord, StoreConfig } from '../types';

export const STORE_COLORS = {
  shibuya: '#3b82f6',
  shinjuku: '#ec4899',
  ikebukuro: '#10b981',
} as const;

export const STORE_CONFIGS: readonly StoreConfig[] = Object.freeze([
  Object.freeze({
    id: 'shibuya' as const,
    name: '渋谷店',
    color: STORE_COLORS.shibuya,
    key: 'shibuya' as const,
  }),
  Object.freeze({
    id: 'shinjuku' as const,
    name: '新宿店',
    color: STORE_COLORS.shinjuku,
    key: 'shinjuku' as const,
  }),
  Object.freeze({
    id: 'ikebukuro' as const,
    name: '池袋店',
    color: STORE_COLORS.ikebukuro,
    key: 'ikebukuro' as const,
  }),
]);

export const MONTHLY_VISITOR_DATA: readonly MonthlyVisitorRecord[] = Object.freeze([
  Object.freeze({ month: '1月', shibuya: 12400, shinjuku: 14200, ikebukuro: 9800 }),
  Object.freeze({ month: '2月', shibuya: 11800, shinjuku: 13500, ikebukuro: 9200 }),
  Object.freeze({ month: '3月', shibuya: 15600, shinjuku: 16800, ikebukuro: 12100 }),
  Object.freeze({ month: '4月', shibuya: 16200, shinjuku: 17500, ikebukuro: 12800 }),
  Object.freeze({ month: '5月', shibuya: 17800, shinjuku: 18900, ikebukuro: 13600 }),
  Object.freeze({ month: '6月', shibuya: 14500, shinjuku: 15400, ikebukuro: 11400 }),
  Object.freeze({ month: '7月', shibuya: 18200, shinjuku: 19600, ikebukuro: 14200 }),
  Object.freeze({ month: '8月', shibuya: 19500, shinjuku: 21300, ikebukuro: 15800 }),
  Object.freeze({ month: '9月', shibuya: 15900, shinjuku: 16900, ikebukuro: 12500 }),
  Object.freeze({ month: '10月', shibuya: 17100, shinjuku: 18200, ikebukuro: 13400 }),
  Object.freeze({ month: '11月', shibuya: 16800, shinjuku: 17800, ikebukuro: 13100 }),
  Object.freeze({ month: '12月', shibuya: 21400, shinjuku: 23600, ikebukuro: 17200 }),
]);

export const getStoreConfigs = (): StoreConfig[] => {
  return STORE_CONFIGS as StoreConfig[];
};

export const getMonthlyData = (): MonthlyVisitorRecord[] => {
  return MONTHLY_VISITOR_DATA as MonthlyVisitorRecord[];
};

import { StoreStats, VisibleStoresState } from '../types';

interface SummaryCardsProps {
  stats?: StoreStats[];
  visibleStores?: VisibleStoresState;
}

export default function SummaryCards({
  stats = [],
  visibleStores = { shibuya: true, shinjuku: true, ikebukuro: true },
}: SummaryCardsProps) {
  const filteredStats = stats.filter((stat) => visibleStores[stat.id] ?? true);

  if (filteredStats.length === 0) {
    return (
      <div className="summary-grid" role="region" aria-label="店舗別サマリー情報">
        <div
          className="summary-card"
          style={{ gridColumn: '1 / -1' }}
          role="status"
          aria-live="polite"
        >
          <p className="summary-title">表示対象の店舗が選択されていません</p>
          <p className="summary-subtext">
            上部の店舗チェックボックスをオンにしてください。
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="summary-grid" role="region" aria-label="店舗別サマリー情報">
      {filteredStats.map((stat) => {
        const isMultipleMonths = stat.maxMonth.includes(',');
        const maxMonthLabel = isMultipleMonths ? '最多来客月(タイ)' : '最多来客月';
        const maxMonthDisplay =
          stat.maxMonth === '-'
            ? '-'
            : `${stat.maxMonth} (${stat.maxValue.toLocaleString()}人)`;

        return (
          <article
            key={stat.id}
            className="summary-card"
            aria-label={`${stat.name}の実績サマリー`}
          >
            <div className="summary-card-header">
              <h3 className="summary-title">
                <span
                  className="store-color-badge"
                  style={{ backgroundColor: stat.color }}
                  aria-hidden="true"
                />
                {stat.name}
              </h3>
            </div>

            <div
              className="summary-value"
              aria-label={`期間内合計来客数 ${stat.total.toLocaleString()}人`}
            >
              {stat.total.toLocaleString()}
              <small>人</small>
            </div>

            <dl className="summary-subtext">
              <div className="summary-subtext-item">
                <dt>期間内月平均</dt>
                <dd>
                  <strong>{stat.average.toLocaleString()}人 / 月</strong>
                </dd>
              </div>
              <div className="summary-subtext-item">
                <dt>{maxMonthLabel}</dt>
                <dd>
                  <strong>{maxMonthDisplay}</strong>
                </dd>
              </div>
            </dl>
          </article>
        );
      })}
    </div>
  );
}

import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  TooltipProps,
} from 'recharts';
import { MonthlyVisitorRecord, StoreConfig, VisibleStoresState } from '../types';

interface VisitorChartProps {
  data?: MonthlyVisitorRecord[];
  stores?: StoreConfig[];
  visibleStores?: VisibleStoresState;
}

interface CustomTooltipPayloadItem {
  name?: string;
  value?: number;
  color?: string;
  dataKey?: string | number;
}

const CustomTooltip = ({
  active,
  payload,
  label,
}: TooltipProps<number, string>) => {
  if (active && payload && payload.length > 0) {
    return (
      <div className="custom-tooltip" role="tooltip">
        <p className="tooltip-label">{label}</p>
        {(payload as CustomTooltipPayloadItem[]).map((entry, index) => (
          <div key={entry.dataKey ?? index} className="tooltip-item">
            <span className="tooltip-item-left">
              <span
                className="tooltip-color-dot"
                style={{ backgroundColor: entry.color ?? '#64748b' }}
                aria-hidden="true"
              />
              <span>{entry.name ?? ''}</span>
            </span>
            <span className="tooltip-item-value">
              {typeof entry.value === 'number'
                ? `${entry.value.toLocaleString()}人`
                : '-'}
            </span>
          </div>
        ))}
      </div>
    );
  }
  return null;
};

export default function VisitorChart({
  data = [],
  stores = [],
  visibleStores = { shibuya: true, shinjuku: true, ikebukuro: true },
}: VisitorChartProps) {
  const activeStores = stores.filter(
    (store) => visibleStores[store.id] ?? true
  );

  return (
    <div className="chart-card">
      <div className="chart-header">
        <h2 className="chart-title">月別来客数推移</h2>
        <span className="chart-subtitle">単位: 人（月間総来客数）</span>
      </div>

      <div className="chart-wrapper">
        {activeStores.length === 0 ? (
          <div
            className="chart-empty-message"
            style={{ minHeight: '320px' }}
            role="status"
          >
            <svg
              width="48"
              height="48"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.5"
              strokeLinecap="round"
              strokeLinejoin="round"
              aria-hidden="true"
              style={{ opacity: 0.4, marginBottom: '4px' }}
            >
              <circle cx="12" cy="12" r="10" />
              <line x1="12" y1="8" x2="12" y2="12" />
              <line x1="12" y1="16" x2="12.01" y2="16" />
            </svg>
            <p>表示する店舗が選択されていません。</p>
            <p>操作パネルから1つ以上の店舗を選択してください。</p>
          </div>
        ) : (
          <ResponsiveContainer width="100%" height="100%">
            <LineChart
              data={data}
              margin={{ top: 20, right: 30, left: 10, bottom: 10 }}
            >
              <CartesianGrid
                strokeDasharray="3 3"
                stroke="#e2e8f0"
                vertical={false}
              />
              <XAxis
                dataKey="month"
                stroke="#64748b"
                tick={{ fontSize: 12 }}
                tickLine={false}
                axisLine={{ stroke: '#cbd5e1' }}
              />
              <YAxis
                stroke="#64748b"
                tick={{ fontSize: 12 }}
                tickLine={false}
                axisLine={false}
                tickFormatter={(value: number) =>
                  value >= 10000
                    ? `${(value / 10000).toFixed(1)}万人`
                    : `${value.toLocaleString()}人`
                }
              />
              <Tooltip content={<CustomTooltip />} />
              <Legend
                verticalAlign="bottom"
                iconType="circle"
                wrapperStyle={{ paddingTop: 16 }}
              />
              {activeStores.map((store) => (
                <Line
                  key={store.id}
                  type="monotone"
                  dataKey={store.key}
                  name={store.name}
                  stroke={store.color}
                  strokeWidth={3}
                  activeDot={{
                    r: 7,
                    stroke: '#ffffff',
                    strokeWidth: 2,
                  }}
                  dot={{
                    r: 4,
                    fill: store.color,
                    stroke: '#ffffff',
                    strokeWidth: 1.5,
                  }}
                />
              ))}
            </LineChart>
          </ResponsiveContainer>
        )}
      </div>
    </div>
  );
}

import { useState, useMemo, useCallback } from 'react';
import { FilterPeriod, StoreConfig, VisibleStoresState, StoreKey } from './types';
import { getStoreConfigs, getMonthlyData } from './data/mockData';
import { filterMonthlyDataByPeriod, calculateStoreStats } from './utils/analytics';
import VisitorChart from './components/VisitorChart';
import SummaryCards from './components/SummaryCards';

const PERIOD_OPTIONS: { id: FilterPeriod; label: string }[] = [
  { id: 'all', label: '通年 (1〜12月)' },
  { id: 'first-half', label: '上半期 (1〜6月)' },
  { id: 'second-half', label: '下半期 (7〜12月)' },
  { id: 'last-3-months', label: '直近3ヶ月 (10〜12月)' },
];

const createInitialStoreState = (
  configs: readonly StoreConfig[],
  defaultValue = true
): VisibleStoresState => {
  return configs.reduce<VisibleStoresState>(
    (acc, store) => {
      acc[store.id] = defaultValue;
      return acc;
    },
    {} as VisibleStoresState
  );
};

export default function App() {
  const storeConfigs = useMemo(() => getStoreConfigs(), []);
  const allMonthlyData = useMemo(() => getMonthlyData(), []);

  const [period, setPeriod] = useState<FilterPeriod>('all');
  const [visibleStores, setVisibleStores] = useState<VisibleStoresState>(() =>
    createInitialStoreState(storeConfigs, true)
  );

  const handlePeriodChange = (selectedPeriod: FilterPeriod) => {
    setPeriod(selectedPeriod);
  };

  const handleStoreToggle = (storeId: StoreKey) => {
    setVisibleStores((prev) => ({
      ...prev,
      [storeId]: !prev[storeId],
    }));
  };

  const handleSelectAllStores = useCallback(() => {
    setVisibleStores(createInitialStoreState(storeConfigs, true));
  }, [storeConfigs]);

  const handleDeselectAllStores = useCallback(() => {
    setVisibleStores(createInitialStoreState(storeConfigs, false));
  }, [storeConfigs]);

  const handleReset = useCallback(() => {
    setPeriod('all');
    setVisibleStores(createInitialStoreState(storeConfigs, true));
  }, [storeConfigs]);

  const filteredMonthlyData = useMemo(() => {
    return filterMonthlyDataByPeriod(allMonthlyData, period);
  }, [allMonthlyData, period]);

  const stats = useMemo(() => {
    return calculateStoreStats(storeConfigs, filteredMonthlyData);
  }, [storeConfigs, filteredMonthlyData]);

  return (
    <div className="app-container">
      <header className="app-header">
        <h1 className="header-title">店舗別来客数ダッシュボード</h1>
        <p className="header-subtitle">
          渋谷店・新宿店・池袋店の年間月別来客実績の推移と指標比較
        </p>
      </header>

      <section className="control-panel">
        <div className="filter-group">
          <span className="filter-label">表示期間</span>
          <div className="filter-btn-group">
            {PERIOD_OPTIONS.map((opt) => (
              <button
                key={opt.id}
                type="button"
                className={`filter-btn ${
                  period === opt.id ? 'filter-btn-active' : ''
                }`}
                onClick={() => handlePeriodChange(opt.id)}
              >
                {opt.label}
              </button>
            ))}
          </div>
        </div>

        <div className="filter-group">
          <span className="filter-label">店舗表示切替</span>
          <div className="store-toggles">
            {storeConfigs.map((store) => {
              const isChecked = visibleStores[store.id] ?? false;
              return (
                <label key={store.id} className="store-toggle-item">
                  <input
                    type="checkbox"
                    className="store-checkbox"
                    checked={isChecked}
                    onChange={() => handleStoreToggle(store.id)}
                  />
                  <span
                    className="store-color-badge"
                    style={{ backgroundColor: store.color }}
                  />
                  <span>{store.name}</span>
                </label>
              );
            })}
            <button
              type="button"
              className="reset-btn"
              onClick={handleSelectAllStores}
            >
              全店舗表示
            </button>
            <button
              type="button"
              className="reset-btn"
              onClick={handleDeselectAllStores}
            >
              全選択解除
            </button>
          </div>
        </div>

        <button type="button" className="reset-btn" onClick={handleReset}>
          初期設定に戻す
        </button>
      </section>

      <SummaryCards stats={stats} visibleStores={visibleStores} />

      <VisitorChart
        data={filteredMonthlyData}
        stores={storeConfigs}
        visibleStores={visibleStores}
      />
    </div>
  );
}

import { MonthlyVisitorRecord, StoreConfig, StoreStats, FilterPeriod } from '../types';

export const filterMonthlyDataByPeriod = (
  data: readonly MonthlyVisitorRecord[],
  period: FilterPeriod
): MonthlyVisitorRecord[] => {
  switch (period) {
    case 'first-half':
      return data.slice(0, 6);
    case 'second-half':
      return data.slice(6, 12);
    case 'last-3-months':
      return data.slice(9, 12);
    case 'all':
    default:
      return [...data];
  }
};

export const calculateStoreStats = (
  configs: readonly StoreConfig[],
  data: readonly MonthlyVisitorRecord[]
): StoreStats[] => {
  if (data.length === 0) {
    return configs.map((store) => ({
      id: store.id,
      name: store.name,
      color: store.color,
      total: 0,
      average: 0,
      maxMonth: '-',
      maxValue: 0,
    }));
  }

  return configs.map((store) => {
    let total = 0;
    let maxValue = -1;
    let maxMonth = '-';

    data.forEach((row) => {
      const val = row[store.key];
      total += val;
      if (val > maxValue) {
        maxValue = val;
        maxMonth = row.month;
      }
    });

    const average = Math.round(total / data.length);

    return {
      id: store.id,
      name: store.name,
      color: store.color,
      total,
      average,
      maxMonth,
      maxValue: maxValue < 0 ? 0 : maxValue,
    };
  });
};
